"""What the committed fixture XML must be true of, read from the file (plan T4.5). No Docker.

`test_05_fixture.py` proves the fixture *imports* the way `cast.py` says. It needs Docker and a
live instance, so it is on the advisory leg — which makes it the wrong place for the one property
every `search_person` assertion in all three matrices silently depends on.

That property is a naming invariant: **no name in the fixture is a substring of any other.**
`search_person` is a case-insensitive substring match over `[first, surname, "first surname",
nick]` of the primary name *and* of every alternate name (`gramps_client.py:239-251, 845`). So the
moment one name contains another, a case asserting "this query returns N rows" starts returning
N+1 for a reason that has nothing to do with the tool. It holds today by luck rather than by rule
— and T4.5 adds eighteen people, which is exactly the edit that would break it. It is asserted
here, on the required leg, and it is asserted *before* those names exist.

The membership half is the fixture's other unchecked seam: `cast.FAMILIES` records the *arguments*
`gramps_add_family` was called with, and the XML records what the server did with them. They agree
as sets today. They are compared as sets deliberately — which slot each spouse landed in is a
measured value that `cast.py` does not yet carry, and pinning it here would re-derive the
product's rule inside a test. T4.5 records the slots, and then this tightens.
"""

from __future__ import annotations

import xml.etree.ElementTree as ET
from collections.abc import Iterable
from itertools import permutations
from pathlib import Path

import pytest
from fixtures import cast

FIXTURE = Path(__file__).parent / "fixtures" / "synthetic-tree.gramps"


def collisions(names: Iterable[str]) -> list[tuple[str, str]]:
    """Every ordered pair where the first name is contained in the second.

    Case-insensitive, because the live match is (`gramps_client.py:845`): a fixture that avoided
    collisions only by capitalisation would read as clean here and go ambiguous on the wire.
    Distinct values only — two people may share a name, and often do.
    """
    lowered = sorted({name.lower() for name in names})
    return [(a, b) for a, b in permutations(lowered, 2) if a in b]


class Fixture:
    """The committed XML, read as ids — the same vocabulary `cast.py` speaks."""

    def __init__(self, path: Path) -> None:
        root = ET.parse(path).getroot()
        self.ns = root.tag.split("}")[0][1:]
        self.people = {person.get("handle"): person for person in root.iter(self.q("person"))}
        self.families = list(root.iter(self.q("family")))
        self.id_of = {handle: person.get("id") for handle, person in self.people.items()}

    def q(self, tag: str) -> str:
        return f"{{{self.ns}}}{tag}"

    def slots(self, family: ET.Element) -> tuple[str | None, str | None]:
        def link(tag: str) -> str | None:
            element = family.find(self.q(tag))
            return self.id_of.get(element.get("hlink")) if element is not None else None

        return link("father"), link("mother")

    def children(self, family: ET.Element) -> set[str]:
        return {
            self.id_of[ref.get("hlink")]
            for ref in family.iter(self.q("childref"))
            if ref.get("hlink") in self.id_of
        }

    def names(self) -> set[str]:
        """Every given name and every surname, primary and alternate, as one set.

        One set rather than two, because `search_person` does not distinguish them: a given name
        that is a substring of somebody's surname is the same defect as two colliding surnames.
        """
        found: set[str] = set()
        for person in self.people.values():
            for name in person.iter(self.q("name")):
                for tag in ("first", "surname"):
                    value = name.findtext(self.q(tag))
                    if value:
                        found.add(value)
        return found


@pytest.fixture(scope="module")
def fixture() -> Fixture:
    return Fixture(FIXTURE)


def test_the_fixture_parses_into_the_records_the_cast_declares(fixture: Fixture) -> None:
    """Every check below is green on an empty parse; this is what makes them mean something."""
    assert len(fixture.people) == cast.COUNTS["people"]
    assert len(fixture.families) == cast.COUNTS["families"]


def test_no_name_in_the_fixture_is_a_substring_of_another(fixture: Fixture) -> None:
    """`search_person("Anselm")` must not also find an `Anselma`. This is the invariant that
    makes a count assertion in a matrix a statement about the tool rather than about luck."""
    found = collisions(fixture.names())

    assert not found, "one fixture name contains another: " + "; ".join(
        f"{a!r} inside {b!r}" for a, b in found
    )


def test_the_fixture_actually_offers_names_to_compare(fixture: Fixture) -> None:
    """A `names()` that returned nothing would make the check above green forever."""
    assert len(fixture.names()) > 30


def test_the_collision_check_catches_the_collisions_it_is_for() -> None:
    """The three the extension nearly introduced, plus the case-only one. Without this the
    invariant is a comprehension nobody has ever seen report anything."""
    assert collisions(["Anselm", "Anselma"]) == [("anselm", "anselma")]
    assert collisions(["Steinbrecht", "Stein"]) == [("stein", "steinbrecht")]
    assert collisions(["Wendelmark", "wendel"]) == [("wendel", "wendelmark")]
    assert collisions(["Falkenrieder", "FALKENRIEDER"]) == []


def test_every_family_holds_the_people_the_cast_says(fixture: Fixture) -> None:
    """Per slot, since T4.5 measured them. `cast.FAMILIES` now records `father`/`mother` as the
    server assigned them, next to the `spouse_a`/`spouse_b` it was *called* with, so this can
    compare the file against a measurement instead of against a rule re-derived from the code
    under test. It is the guard that makes the family-graph group's premise — that a parent slot
    is bloodline and not gender — something a mutation can break."""
    declared = {entry["gramps_id"]: entry for entry in cast.FAMILIES}

    for family in fixture.families:
        entry = declared[family.get("id")]
        father, mother = fixture.slots(family)

        assert (father or "") == entry["father"], family.get("id")
        assert (mother or "") == entry["mother"], family.get("id")
        assert fixture.children(family) == set(entry["children"]), family.get("id")


def test_the_slots_are_not_merely_the_call_order(fixture: Fixture) -> None:
    """Otherwise the check above would be satisfied by a cast that copied `spouse_a` into
    `father`, which is exactly the mistake it exists to prevent. Six of these families have a
    female in the father slot; at least one must disagree with a gender-based reading."""
    surprising = [
        entry
        for entry in cast.FAMILIES
        if entry["father"] and entry["mother"] and entry["father"] != entry["spouse_a"]
    ]
    genders = {person["gramps_id"]: person["gender"] for person in cast.PEOPLE}
    female_fathers = [entry for entry in cast.FAMILIES if genders.get(entry["father"]) == 0]

    assert female_fathers, "no family has a female in the father slot — the shape is gone"
    assert surprising or female_fathers


def test_every_declared_family_is_in_the_xml(fixture: Fixture) -> None:
    """The loop above is over the XML, so a family the cast declares and the file lost would
    never be visited."""
    assert {family.get("id") for family in fixture.families} == {
        entry["gramps_id"] for entry in cast.FAMILIES
    }
